{
  "selections": [
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '사람 만나는 게 피곤해졌다'는 부분에 대해 더 자세히 물어보았고, 이 규칙(항상 괜찮은 모습만 보여야 함)이 사교 활동에서 지속적 에너지 소모가 발생하는 메커니즘을 설명함. 성장 배경에서 '괜찮아 보이는 모습'을 보여야만 인정을 받은 경험이 이 규칙의 원천임."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "사람을 만나는 게 피곤해진 이유가 약점이나 진짜 감정을 들키는 것에 대한 두려움(이 태도)과 연결됨. 내담자가 '어디서부터 말해야 할지 모르겠다'며 말문을 여는 데 어려움을 보인 것도 이 태도와 관련됨."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "사람 만나는 게 피곤해진 현상의 저변에 '진짜 나를 알면 떠날 것'이라는 핵심 신념이 작용하고 있음. 상담사가 이 피로감의 변화를 확인하려는 질문을 한 맥락과 연결됨."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": [],
      "relevance": "항상 밝고 문제없는 모습을 유지하며 힘든 감정을 혼자 삭히는 전략이 사교 활동의 에너지 소모를 직접적으로 설명함. 내담자가 '피곤해지긴 했어요'라고 표현한 현상과 일치."
    },
    {
      "trait_id": "/coping_strategies/2",
      "background_ids": ["/situations/1"],
      "relevance": "관계가 가까워지면 만남 자체를 줄이는 패턴이 '사람 만나는 게 피곤해졌다'는 표현의 행동적 측면을 설명함. 연인이 '무슨 생각을 하는지 모르겠다'고 한 것은 이 전략이 작동한 결과임."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/situations/3"],
      "relevance": "내담자가 '잠도 잘 못 자고'라고 언급한 부분과, 밤에 예전 실수 순간이 떠올라 잠을 미루는 상황 사례가 결함/수치심 도메인과 연결됨. 상담사가 이 증상을 확인하는 맥락에서 관련됨."
    }
  ]
}

